from typing import List, Optional
import models.generated_file
from sqlalchemy import select, update, delete, desc
from sqlalchemy.engine import Engine
from sqlalchemy.orm import Session


class GeneratedFilesDB:
    """Wrapper class for managing files generated by actions"""

    engine: Engine

    def __init__(self, db: Engine):
        self.engine = db

    def fetch_execution_files(
            self, exec_id: str) -> List[models.generated_file.GeneratedFile]:
        """Fetches a list of all generated files for a given execution,
        sorted by their names (ascending).
        """
        try:
            with Session(self.engine) as session:
                stmt = (
                    select(models.generated_file.GeneratedFile)
                    .where(models.generated_file.GeneratedFile.exec_id == exec_id)
                    .order_by(models.generated_file.GeneratedFile.filename)
                )
                files = session.scalars(stmt)
                if files is None:
                    return []
                return [x for x in files]
        except Exception as e:
            print("Fetching generated files failed:", repr(e))
            return []

    def insert(self, generated_file: models.generated_file.GeneratedFile):
        """Add generated file to the database"""
        with Session(self.engine) as session:
            session.add(generated_file)
            session.commit()
            session.refresh(generated_file)
            return generated_file.exec_id, generated_file.filename

    def delete_execution_generated_files(self, exec_id: str):
        """Remove all files for a given execution.
        """
        with Session(self.engine) as session:
            stmt = (
                delete(models.generated_file.GeneratedFile)
                .where(models.generated_file.GeneratedFile.exec_id == exec_id)
            )
            session.execute(stmt)
            session.commit()
